// CrowdStrike CQL for Mule Account Velocity Pattern
// Repository: flame-banking-transaction-monitoring
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection_inbound | count(distinct originator_name) by account_id > 3
transaction_type="ACH_IN"
| groupBy(account_id, function=[count(as=event_count), collect(originator_name)])
| event_count > 3
